 public void Tick(FlightModel f,bool playing,bool ended,float dt){clock+=dt;if(ended)endClock+=dt;else endClock=0;float alt=f==null?80:f.Altitude;float heat=f==null?0:f.Heat;float attack=f==null?.28f:f.Attack;
