 static Mesh Globe(){int rows=96,cols=192;var v=new Vector3[(rows+1)*(cols+1)];var normals=new Vector3[v.Length];var indices=new int[rows*cols*6];int k=0;for(int y=0;y<=rows;y++)for(int x=0;x<=cols;x++){float a=Mathf.PI*y/rows,b=Mathf.PI*2*x/cols;var n=new Vector3(Mathf.Sin(a)*Mathf.Cos(b),Mathf.Cos(a),Mathf.Sin(a)*Mathf.Sin(b));v[y*(cols+1)+x]=n*.5f;normals[y*(cols+1)+x]=n;if(y<rows&&x<cols){int i=y*(cols+1)+x;indices[k++]=i;indices[k++]=i+1;indices[k++]=i+cols+1;indices[k++]=i+1;indices[k++]=i+cols+2;indices[k++]=i+cols+1;}}var m=new Mesh();m.vertices=v;m.normals=normals;m.triangles=indices;m.RecalculateBounds();return m;}
